import numpy as np
from scipy.optimize import least_squares
t=np.asarray(df['t']);P=np.asarray(df['P']);y=np.asarray(df['dP_dt'])
Pf={'1':P*0+1,'P':P,'P2':P**2,'1/P':1/P,'PlogP':P*np.log(P),'logP':np.log(P)}
def run(Pk,Tk):
    def cols(w):
        T={'1':1+0*t,'t':t,'s':np.sin(w*t),'c':np.cos(w*t),'e':np.exp(-t),'lt':np.log(t),'sq':np.sqrt(t),'t2':t**2}
        return np.c_[tuple(Pf[p]*T[q] for p in Pk for q in Tk)]
    def res(p):
        A=cols(p[0]); c,*_=np.linalg.lstsq(A,y,rcond=None); return np.sqrt(np.mean((A@c-y)**2))/np.std(y)
    best=min((res([w]),w) for w in np.linspace(0.1,3,60))
    r=least_squares(lambda p: [res(p)], [best[1]])
    return r.x[0], res(r.x)
print(run(['1','P','P2','1/P'],['1','t','s','c']))
print(run(['1','P','P2','1/P','PlogP','logP'],['1','s','c']))
